}

class Lesson {
  + date : date
  + startTime : time
  + duration : int
}

class Resource {
  + name : string
}

abstract class Teacher {
  + name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

class MasterStudent {}

class ExternalAuditor {}

class CourseEditionEnrollment {
}

class LessonResource {
}

Course "1" *-- "1..*" Edition
Edition "1" *-- "1..*" Lesson
Course "1" -- "1" InternalTeacher : responsible

Teacher "0..*" -- "0..*" Lesson : teaches

Teacher "0..*" -- "0..*" Course : assigned_to

Edition "1" -- "0..*" MasterStudent : enrolled
Edition "1" -- "0..*" ExternalAuditor : enrolled

Lesson "1" -- "0..*" LessonResource
LessonResource "*" -- "1" Resource

@enduml

